package com.gr4nt.filexplorer;
import java.io.*;import java.util.*;import java.security.*;import java.security.cert.X509Certificate;
import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.baksmali.*;import org.jf.smali.*;
import com.android.apksig.*;
public final class ApkWorkshop {
 public static String dexInfo(File file)throws IOException{DexFile dex=DexFileFactory.loadDexFile(file,Opcodes.getDefault());StringBuilder s=new StringBuilder();int methods=0,fields=0;for(ClassDef c:dex.getClasses()){for(Method m:c.getMethods())methods++;for(Field f:c.getFields())fields++;}s.append("Classes: ").append(dex.getClasses().size()).append("\nMethods: ").append(methods).append("\nFields: ").append(fields).append("\n\n");for(ClassDef c:dex.getClasses())s.append(c.getType()).append('\n');return s.toString();}
 public static void disassemble(File dex,File output)throws IOException{if(output.exists())throw new IOException("Output folder exists");if(!output.mkdirs())throw new IOException("Could not create output");BaksmaliOptions options=new BaksmaliOptions();options.apiLevel=35;if(!Baksmali.disassembleDexFile(DexFileFactory.loadDexFile(dex,Opcodes.getDefault()),output,2,options))throw new IOException("DEX disassembly failed");}
 public static void assemble(File directory,File output)throws IOException{if(output.exists())throw new IOException("Output exists");SmaliOptions options=new SmaliOptions();options.apiLevel=35;options.outputDexFile=output.getPath();if(!Smali.assemble(options,Collections.singletonList(directory.getPath())))throw new IOException("Smali assembly failed");}
 public static void sign(File input,File output,PrivateKey key,X509Certificate cert)throws Exception{if(output.exists())throw new IOException("Output exists");ApkSigner.SignerConfig config=new ApkSigner.SignerConfig.Builder("File-Xplorer",key,Collections.singletonList(cert)).build();new ApkSigner.Builder(Collections.singletonList(config)).setInputApk(input).setOutputApk(output).setMinSdkVersion(26).setV1SigningEnabled(false).setV2SigningEnabled(true).setV3SigningEnabled(true).build().sign();}
 public static String verify(File file)throws Exception{ApkVerifier.Result r=new ApkVerifier.Builder(file).build().verify();StringBuilder text=new StringBuilder("Verified: "+r.isVerified()+"\nv1: "+r.isVerifiedUsingV1Scheme()+"\nv2: "+r.isVerifiedUsingV2Scheme()+"\nv3: "+r.isVerifiedUsingV3Scheme()+"\n");for(X509Certificate c:r.getSignerCertificates()){byte[] digest=MessageDigest.getInstance("SHA-256").digest(c.getEncoded());text.append("\nSigner: ").append(c.getSubjectX500Principal()).append("\nSHA-256: ");for(byte b:digest)text.append(String.format("%02x",b));}for(Object e:r.getErrors())text.append("\n").append(e);return text.toString();}
}
